using System;
using System.IO;
using System.Net;
using System.Net.Sockets;
using System.Diagnostics;
using System.Reflection;
using System.Collections.Generic;
using System.Threading;
using System.Text;
using AuroraProxy;
class AuditCoreTests {
 static int count;
 static void Check(bool ok,string name){if(!ok)throw new Exception("FAIL: "+name);count++;Console.WriteLine("PASS: "+name);}
 static void Reject(Action a,string name){try{a();}catch(Exception){Check(true,name);return;}Check(false,name);}
 static int Port(){var l=new TcpListener(IPAddress.Loopback,0);l.Start();int p=((IPEndPoint)l.LocalEndpoint).Port;l.Stop();return p;}
 static string Now(Engine e,string group){return e.Api("GET","/proxies/"+Uri.EscapeDataString(group),null)["now"].ToString();}
 static void Select(Engine e,string group,string node){e.Api("PUT","/proxies/"+Uri.EscapeDataString(group),new Dictionary<string,object>{{"name",node}});}
 static bool Held(Engine e,int port){foreach(var c in ConnectionInfo.Parse(e.Api("GET","/connections",null)))if(c.Target.EndsWith(":"+port))return true;return false;}
 static TcpClient Accept(TcpListener listener){var watch=Stopwatch.StartNew();while(!listener.Pending()){if(watch.ElapsedMilliseconds>5000)throw new TimeoutException("Origin was not reached");Thread.Sleep(20);}return listener.AcceptTcpClient();}
 static int Main(string[] args){string root=Path.Combine(Path.GetTempPath(),"aurora-audit-"+Guid.NewGuid().ToString("N"));Engine engine=null;TcpListener upstream=null;TcpListener hold=null;
  try{var store=new Store(root);store.State.CorePath=Path.GetFullPath(args[0]);store.State.Port=Port();store.State.ApiPort=Port();int upstreamPort=Port();
   string yaml="notes: |\n  ---\n  ...\nproxies:\n- name: A\n  type: http\n  server: 127.0.0.1\n  port: "+upstreamPort+"\n- name: B\n  type: http\n  server: 127.0.0.1\n  port: "+upstreamPort+"\nproxy-groups:\n- name: PICK\n  type: select\n  proxies: [A, B]\nrules:\n- MATCH,DIRECT\n";
   var p=new Subscription(){Name="audit"};store.State.Profiles.Add(p);store.State.Active=p.Id;Store.Atomic(store.ProfilePath(p),yaml);store.Save();engine=new Engine(store);
   engine.Validate(engine.Build("--- # one document\n"+yaml+"... # end\n"));Check(true,"real core accepts indentless root sequences and literal document markers");
   string built=engine.Build("authentication:\n- old:secret\n"+yaml);Check(!built.Contains("old:secret"),"indentless owned sequence is removed in full");engine.Validate(built);Check(true,"owned sequence override remains valid YAML");
   Reject(delegate{Config.Build(yaml,100,19090,"rule","s");},"invalid ports rejected before core launch");Reject(delegate{Config.Build(yaml,7890,19090,"broken","s");},"invalid config mode rejected");
   var settings=store.State;string settingsPath=Path.Combine(root,"settings.json"),backup=settingsPath+".backup";File.Move(settingsPath,backup);Directory.CreateDirectory(settingsPath);Reject(delegate{store.UpdateSettings(delegate(Settings value){value.Port=19091;value.Dark=false;});},"settings write failure surfaces");Check(Object.ReferenceEquals(store.State,settings)&&store.State.Port==settings.Port&&store.State.Dark==settings.Dark,"failed settings update retains original state");Directory.Delete(settingsPath);File.Move(backup,settingsPath);
   engine.Start(p);using(var socket=new TcpClient()){socket.ReceiveTimeout=1500;socket.Connect(IPAddress.Loopback,store.State.Port);var stream=socket.GetStream();stream.Write(new byte[]{5,1,0},0,3);Check(stream.ReadByte()==5&&stream.ReadByte()==0,"startup completion includes a ready mixed SOCKS endpoint");}int generation=engine.Generation;Check(Now(engine,"GLOBAL")=="DIRECT","new core GLOBAL starts with independent DIRECT selection");Reject(delegate{engine.ChangeMode("global");},"unconfigured GLOBAL is rejected before changing mode");Check(store.State.Mode=="rule"&&engine.Api("GET","/configs",null)["mode"].ToString()=="rule","rejected global switch preserves rule mode");
   Select(engine,"GLOBAL","PICK");Select(engine,"PICK","B");Check(engine.GlobalTarget()=="B","GLOBAL follows nested policy group to actual proxy");engine.ChangeMode("global");Check(store.State.Mode=="global"&&engine.Api("GET","/configs",null)["mode"].ToString()=="global","configured global switch updates core and saved mode");
   upstream=new TcpListener(IPAddress.Loopback,upstreamPort);upstream.Start();int requests=0;var server=new Thread(delegate(){try{while(true){using(var c=upstream.AcceptTcpClient()){c.ReceiveTimeout=5000;var stream=c.GetStream();var reader=new StreamReader(stream);string first=reader.ReadLine(),line;while((line=reader.ReadLine())!=null&&line!=""){}if(first==null||!first.StartsWith("CONNECT "))throw new Exception("Expected proxy CONNECT");byte[] ready=Encoding.ASCII.GetBytes("HTTP/1.1 200 Connection established\r\n\r\n");stream.Write(ready,0,ready.Length);first=reader.ReadLine();while((line=reader.ReadLine())!=null&&line!=""){}Interlocked.Increment(ref requests);byte[] response=Encoding.ASCII.GetBytes("HTTP/1.1 200 OK\r\nContent-Length: 15\r\nConnection: close\r\n\r\nAUDIT-GLOBAL-OK");stream.Write(response,0,response.Length);}}}catch(SocketException){}catch(ObjectDisposedException){}}){IsBackground=true};server.Start();
   using(var c=new TcpClient()){c.ReceiveTimeout=5000;c.Connect(IPAddress.Loopback,store.State.Port);byte[] request=Encoding.ASCII.GetBytes("GET http://audit.invalid/probe HTTP/1.1\r\nHost: audit.invalid\r\nConnection: close\r\n\r\n");c.GetStream().Write(request,0,request.Length);using(var reader=new StreamReader(c.GetStream()))Check(reader.ReadToEnd().Contains("AUDIT-GLOBAL-OK")&&requests==1,"global HTTP request reaches the chosen proxy, not direct route");}
   engine.ChangeMode("rule");hold=new TcpListener(IPAddress.Loopback,0);hold.Start();int holdPort=((IPEndPoint)hold.LocalEndpoint).Port;using(var client=new TcpClient()){client.Connect(IPAddress.Loopback,store.State.Port);byte[] bytes=Encoding.ASCII.GetBytes("GET http://127.0.0.1:"+holdPort+"/hold HTTP/1.1\r\nHost: 127.0.0.1:"+holdPort+"\r\n\r\n");client.GetStream().Write(bytes,0,bytes.Length);using(var origin=Accept(hold)){for(int i=0;i<50&&!Held(engine,holdPort);i++)Thread.Sleep(20);Check(Held(engine,holdPort),"live connection established before identical subscription update");generation=engine.Generation;engine.Apply(p,yaml);Check(engine.Generation==generation&&Held(engine,holdPort)&&Now(engine,"PICK")=="B","identical update retains live connection, selection and generation");}}
   string runtimePath=Path.Combine(store.Work,"config.yaml"),runtimeBackup=runtimePath+".backup";File.Move(runtimePath,runtimeBackup);Directory.CreateDirectory(runtimePath);Reject(delegate{engine.Apply(p,yaml.Replace("name: A","name: C").Replace("[A, B]","[C, B]"));},"runtime cache write failure surfaces before controller reload");Check(engine.Generation==generation&&Now(engine,"PICK")=="B","failed runtime write leaves current core configuration intact");Directory.Delete(runtimePath);File.Move(runtimeBackup,runtimePath);
   File.Move(settingsPath,backup);Directory.CreateDirectory(settingsPath);Reject(delegate{engine.ChangeMode("global");},"failed mode persistence surfaces");Check(store.State.Mode=="rule"&&engine.Api("GET","/configs",null)["mode"].ToString()=="rule","failed mode save restores core and in-memory mode");Directory.Delete(settingsPath);File.Move(backup,settingsPath);
   Reject(delegate{engine.ChangeMode("unknown");},"invalid mode is rejected by controller wrapper");Check(engine.Api("GET","/configs",null)["mode"].ToString()=="rule","invalid mode cannot alter running core");
   Check(!Engine.FormatUsage("upload=9223372036854775807;download=9223372036854775807;total=9223372036854775807").StartsWith("-"),"large usage values do not overflow negative");
   engine.Stop();Check(!engine.Running&&engine.Generation!=generation,"stop invalidates outstanding snapshots");engine.Start(p);Check(engine.Running,"restart after stop works");engine.Stop();engine.Start(p);int exited=0;engine.Exited+=delegate{Interlocked.Increment(ref exited);};if(SystemProxy.Windows)engine.Proxy.Enable(store.State.Port);var process=(Process)typeof(Engine).GetField("process",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(engine);process.Kill();var wait=Stopwatch.StartNew();while(Thread.VolatileRead(ref exited)==0&&wait.ElapsedMilliseconds<5000)Thread.Sleep(20);Check(exited==1&&!engine.Running&&!engine.Proxy.Owned,"unexpected core exit completes callback and restores owned proxy");engine.Start(p);Check(engine.Running,"core restarts after an unexpected exit without stale process handles");engine.Stop();engine.Dispose();Reject(delegate{engine.Start(p);},"disposed engine rejects queued start");Reject(delegate{engine.ChangeMode("global");},"disposed engine rejects queued mode changes");
   Console.WriteLine("Completed "+count+" audit core checks.");return 0;
  }catch(Exception ex){Console.Error.WriteLine(ex);return 1;}finally{if(engine!=null)engine.Dispose();if(upstream!=null)upstream.Stop();if(hold!=null)hold.Stop();if(Directory.Exists(root))Directory.Delete(root,true);}
 }
}
